<?php
$page_title='รายงานสินค้า';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);$status=$_POST['status']??'';if(in_array($status,['reviewing','resolved','dismissed'],true)){$q=$db->prepare('UPDATE product_reports SET status=?,admin_note=?,reviewed_at=NOW(),reviewed_by=? WHERE id=?');$q->execute([$status,trim($_POST['admin_note']??''),(int)$_SESSION['user_id'],(int)$_POST['id']]);$message='อัปเดตรายงานแล้ว';}}$rows=$db->query('SELECT pr.*,p.name product_name,u.username reporter FROM product_reports pr JOIN products p ON p.id=pr.product_id JOIN users u ON u.id=pr.reporter_id ORDER BY FIELD(pr.status,"open","reviewing","resolved","dismissed"),pr.created_at DESC')->fetchAll();require_once __DIR__.'/../includes/admin_header.php';?><header class="admin-page-header"><div><p class="eyebrow">TRUST & SAFETY</p><h1>รายงานสินค้า</h1><p>ตรวจสอบสินค้าปลอม สินค้าต้องห้าม และรายละเอียดที่ไม่ตรง</p></div></header><?php if($message):?><div class="admin-alert success"><?php echo e($message);?></div><?php endif;?><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>สินค้า</th><th>ผู้รายงาน</th><th>เหตุผล</th><th>สถานะ</th><th>ดำเนินการ</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><a href="<?php echo BASE_URL;?>product-detail.php?id=<?php echo $x['product_id'];?>" target="_blank"><?php echo e($x['product_name']);?></a><small><?php echo e($x['detail']);?></small></td><td><?php echo e($x['reporter']);?></td><td><?php echo e($x['reason']);?></td><td><span class="status-badge <?php echo e($x['status']);?>"><?php echo e($x['status']);?></span></td><td><form method="post" class="table-actions"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="id" value="<?php echo $x['id'];?>"><input name="admin_note" placeholder="หมายเหตุ"><select name="status"><option value="reviewing">กำลังตรวจ</option><option value="resolved">แก้ไขแล้ว</option><option value="dismissed">ยกเลิกคำร้อง</option></select><button class="btn btn-primary">บันทึก</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require_once __DIR__.'/../includes/admin_footer.php';?>
